return $input.all().map(item => {
  const row = item.json;

  // Забираем значение из колонки 'Особенности обуви' (или как она у тебя в шапке)
  const text = String(row['Особенности обуви'] || '').trim();

  let statusResult = 'исправить';

  if (text) {
    // Режем строку по точке с запятой
    const parts = text.split(';').map(p => p.trim()).filter(p => p.length > 0);

    // Нам нужно как минимум 3 заполненных значения
    if (parts.length >= 3) {
      statusResult = 'отлично';
    } else {
      statusResult = 'исправить';
    }
  }

  return {
    json: {
      "Артикул продавца": row['Артикул продавца'] || row['Артикул'],
      "Особенности обуви": text,
      "Статус_Особенности": statusResult
    }
  };
});

